285	/// Wraps a Future in the busy/error lifecycle every onboarding step repeats.
286	/// The mixing state calls [progress] for async actions and [fail] for plain
287	/// validation messages; [busy] and [error] drive the UI.
288	mixin FormProgress<T extends StatefulWidget> on State<T> {
289	  bool _busy = false;
290	  String? _error;
291	  bool get busy => _busy;
292	  String? get error => _error;
293	
294	  /// Sets (or with a null argument, clears) the inline error.
295	  void fail([String? message]) => setState(() => _error = message);
296	
297	  Future<void> progress(Future<void> Function() fn) async {
298	    setState(() {
299	      _busy = true;
300	      _error = null;
301	    });
302	    try {
303	      await fn();
304	    } catch (e) {
305	      if (mounted) setState(() => _error = messageFor(e));
306	    } finally {
307	      if (mounted) setState(() => _busy = false);
308	    }
309	  }
310	}
