5	/// Server error codes the UI branches on. Anything unrecognised becomes [unknown]
6	/// so a new backend code degrades to a generic message instead of crashing.
7	enum ApiError {
8	  noLikesRemaining,
9	  subscriptionInactive,
10	  underAge,
11	  deviceLimitReached,
12	  profileIncomplete,
13	  notRegistered,
14	  blocked,
15	  unknown;
16	
17	  static ApiError parse(String? code) => switch (code) {
18	        'no_likes_remaining' => ApiError.noLikesRemaining,
19	        'subscription_inactive' => ApiError.subscriptionInactive,
20	        'under_min_age' => ApiError.underAge,
21	        'device_account_limit_reached' => ApiError.deviceLimitReached,
22	        'profile_incomplete' => ApiError.profileIncomplete,
23	        'not_registered' => ApiError.notRegistered,
24	        'blocked' => ApiError.blocked,
25	        _ => ApiError.unknown,
26	      };
27	
28	  /// Shown to the user. The like-quota and lapse cases are the ones spec 1.2
29	  /// insists must be explicit rather than a silently failing button.
30	  String get message => switch (this) {
31	        ApiError.noLikesRemaining => 'You have used all your likes for today. Come back tomorrow or upgrade.',
32	        ApiError.subscriptionInactive => 'Your subscription has lapsed. Upgrade to send new likes — your matches and chats are still here.',
33	        ApiError.underAge => 'You must be at least 18 to use Rishta.',
34	        ApiError.deviceLimitReached => 'Too many accounts have been created from this device.',
35	        ApiError.profileIncomplete => 'Finish your profile before browsing.',
36	        ApiError.notRegistered => 'Please sign in again.',
37	        ApiError.blocked => 'This profile is not available.',
38	        ApiError.unknown => 'Something went wrong. Please try again.',
39	      };
40	}
41	
42	class ApiException implements Exception {
43	  ApiException(this.statusCode, this.code, this.raw);
44	
45	  final int statusCode;
46	  final String code;
47	  final String raw;
48	
49	  ApiError get error => ApiError.parse(code);
50	
51	  @override
52	  String toString() => 'ApiException($statusCode, $code)';
53	}
54	
55	typedef TokenProvider = Future<String?> Function();
56	
57	/// Standard report reasons, shared by feed and match reporting.
58	const kReportReasons = ['Inappropriate photos', 'Harassment', 'Fake profile', 'Spam or scam'];
59	
60	/// HTTP client for the Rishta API.
61	///
62	/// Generic over the decoded body: callers pass the parse function, so there is
63	/// one request path for every endpoint rather than a method per route.
64	class Api {
65	  Api({required TokenProvider token, http.Client? client, String? baseUrl})
66	      : _token = token,
67	        _client = client ?? http.Client(),
68	        _base = baseUrl ??
69	            const String.fromEnvironment('API_BASE', defaultValue: 'http://10.0.2.2:3000');
70	
71	  final TokenProvider _token;
72	  final http.Client _client;
73	  final String _base;
74	
75	  static const _timeout = Duration(seconds: 20);
76	
77	  Future<T> get<T>(String path, T Function(Object? json) parse, {Map<String, Object?>? query}) =>
78	      request('GET', path, parse: parse, query: query);
79	
80	  Future<T> post<T>(String path, {Object? body, T Function(Object? json)? parse}) =>
81	      request('POST', path, body: body, parse: parse ?? (json) => json as T);
82	
83	  Future<T> put<T>(String path, {Object? body, T Function(Object? json)? parse}) =>
84	      request('PUT', path, body: body, parse: parse ?? (json) => json as T);
85	
86	  Future<T> delete<T>(String path, {Object? body, T Function(Object? json)? parse}) =>
87	      request('DELETE', path, body: body, parse: parse ?? (json) => json as T);
88	
89	  Future<T> request<T>(
90	    String method,
91	    String path, {
92	    required T Function(Object? json) parse,
93	    Object? body,
94	    Map<String, Object?>? query,
95	  }) async {
96	    final uri = Uri.parse('$_base$path').replace(
97	      queryParameters: query?.map((k, v) => MapEntry(k, v?.toString())),
98	    );
99	
100	    final request = http.Request(method, uri)
101	      ..headers['content-type'] = 'application/json';
102	
103	    final token = await _token();
104	    if (token != null) request.headers['authorization'] = 'Bearer $token';
105	    if (body != null) request.body = jsonEncode(body);
106	
107	    final response = await http.Response.fromStream(await _client.send(request)).timeout(_timeout);
108	    final decoded = response.body.isEmpty ? null : jsonDecode(response.body);
109	
110	    if (response.statusCode >= 400) {
111	      throw ApiException(response.statusCode, _messageOf(decoded), response.body);
112	    }
113	    return parse(decoded);
114	  }
115	
116	  /// Decodes a JSON list into models using the caller's factory.
117	  Future<List<T>> listOf<T>(
118	    String path,
119	    T Function(Map<String, dynamic> json) fromJson, {
120	    Map<String, Object?>? query,
121	    String key = 'items',
122	  }) =>
123	      get<List<T>>(
124	        path,
125	        (json) {
126	          final raw = json is Map<String, dynamic> ? json[key] : json;
127	          return (raw as List<dynamic>? ?? const [])
128	              .map((e) => fromJson(e as Map<String, dynamic>))
129	              .toList(growable: false);
130	        },
131	        query: query,
132	      );
133	
134	
135	  /// NestJS puts the code in `message`, which is a string for a thrown
136	  /// HttpException and a list for a ValidationPipe failure.
137	  static String _messageOf(Object? body) {
138	    if (body is! Map) return 'error';
139	    final message = body['message'];
140	    if (message is String) return message;
141	    if (message is List && message.isNotEmpty) return message.first.toString();
142	    return body['error']?.toString() ?? 'error';
143	  }
144	}
