38	class _MatchTile extends ConsumerWidget {
39	  const _MatchTile({required this.match});
40	
41	  final MatchSummary match;
42	
43	  @override
44	  Widget build(BuildContext context, WidgetRef ref) {
45	    final other = match.other;
46	
47	    return ListTile(
48	      leading: SizedBox.square(
49	        dimension: 52,
50	        child: ClipOval(
51	          child: ProfilePhoto(url: other.primaryPhoto, label: '${other.displayName} profile photo'),
52	        ),
53	      ),
54	      title: ProfileNameBadge(name: other.displayName, age: other.age, verification: other.verification),
55	      subtitle: Text(
56	        other.bio.isEmpty ? (other.location ?? '') : other.bio,
57	        maxLines: 1,
58	        overflow: TextOverflow.ellipsis,
59	      ),
60	      trailing: PopupMenuButton<String>(
61	        // Unmatch lives here rather than behind a swipe: it is destructive and
62	        // should take a deliberate second tap.
63	        itemBuilder: (_) => const [
64	          PopupMenuItem(value: 'unmatch', child: Text('Unmatch')),
65	          PopupMenuItem(value: 'report', child: Text('Report')),
66	        ],
67	        onSelected: (value) async {
68	          final messenger = ScaffoldMessenger.of(context);
69	          if (value == 'unmatch') {
70	            await ref.read(matchesProvider.notifier).unmatch(match.matchId);
71	            messenger.showSnackBar(const SnackBar(content: Text('Unmatched.')));
72	          } else {
73	            await _report(context, ref);
74	          }
75	        },
76	      ),
77	      onTap: () => Navigator.of(context).push(
78	        MaterialPageRoute(builder: (_) => ChatScreen(match: match)),
79	      ),
80	    );
81	  }
82	
83	  Future<void> _report(BuildContext context, WidgetRef ref) async {
84	    final reason = await showDialog<String>(
85	      context: context,
86	      builder: (dialogContext) => SimpleDialog(
87	        title: const Text('Report this profile'),
88	        children: [
89	          for (final r in kReportReasons)
90	            SimpleDialogOption(
91	              onPressed: () => Navigator.of(dialogContext).pop(r),
92	              child: Text(r),
93	            ),
94	        ],
95	      ),
96	    );
97	    if (reason == null) return;
98	    await ref.read(apiProvider).post('/reports', body: {
99	      'reportedId': match.other.userId,
100	      'matchId': match.matchId,
101	      'reason': reason,
102	    });
103	  }
104	}
