130	  final _otpCtrl = TextEditingController();
131	  String? _verificationId;
132	  bool _codeSent = false;
133	  int? _resendToken;
134	
135	  bool _busy = false;
136	  String? _error;
137	
138	  FirebaseAuth get _auth => ref.read(firebaseAuthProvider);
139	
140	  @override
141	  void dispose() {
142	    _tabs.dispose();
143	    _emailCtrl.dispose();
144	    _passwordCtrl.dispose();
145	    _phoneCtrl.dispose();
146	    _otpCtrl.dispose();
147	    super.dispose();
148	  }
