150	  // ─── shared error wrapper ───────────────────────────────────────────────
151	  Future<void> _run(Future<void> Function() fn) async {
152	    setState(() { _busy = true; _error = null; });
153	    try {
154	      await fn();
155	    } on FirebaseAuthException catch (e) {
156	      if (mounted) setState(() => _error = _label(e));
157	    } catch (e) {
158	      if (mounted) setState(() => _error = _generic(e));
159	    } finally {
160	      if (mounted) setState(() => _busy = false);
161	    }
162	  }
163	
164	  static String _label(FirebaseAuthException e) => switch (e.code) {
165	        'invalid-email' => 'That email address is not valid.',
166	        'user-disabled' => 'This account has been disabled.',
167	        'user-not-found' => 'No account found — try creating one.',
168	        'wrong-password' => 'Incorrect password.',
169	        'email-already-in-use' => 'An account already exists for that email.',
170	        'weak-password' => 'Choose a stronger password (8+ characters).',
171	        'invalid-verification-code' => 'That code is incorrect.',
172	        'invalid-phone-number' => 'Enter a valid phone number with the country code.',
173	        'too-many-requests' => 'Too many attempts — please wait a few minutes.',
174	        'network-request-failed' => 'No internet connection.',
175	        _ => e.message ?? 'Something went wrong.',
176	      };
177	
178	  static String _generic(Object e) {
179	    final s = e.toString();
180	    if (s.contains('network') || s.contains('SocketException')) {
181	      return 'No internet connection.';
182	    }
183	    if (s.contains('not configured') || s.contains('PlatformException')) {
184	      return 'Auth service not configured for this environment.';
185	    }
186	    return 'Sign-in failed — please try again.';
187	  }
188	
189	  // ─── Google Sign-In ─────────────────────────────────────────────────────
190	  Future<void> _signInWithGoogle() => _run(() async {
191	        final googleUser = await GoogleSignIn().signIn();
192	        if (googleUser == null) return; // user cancelled
193	        final ga = await googleUser.authentication;
194	        final credential = GoogleAuthProvider.credential(
195	          idToken: ga.idToken,
196	          accessToken: ga.accessToken,
197	        );
198	        await _auth.signInWithCredential(credential);
199	      });
200	
201	  // ─── Email auth ─────────────────────────────────────────────────────────
202	  Future<void> _emailAuth({required bool create}) => _run(() async {
203	        final email = _emailCtrl.text.trim();
204	        final pass = _passwordCtrl.text;
205	        if (email.isEmpty || pass.isEmpty) throw Exception('Please fill in email and password.');
206	        if (create) {
207	          await _auth.createUserWithEmailAndPassword(email: email, password: pass);
208	        } else {
209	          await _auth.signInWithEmailAndPassword(email: email, password: pass);
210	        }
211	      });
212	
213	  // ─── Phone: send OTP ────────────────────────────────────────────────────
214	  Future<void> _sendOtp() => _run(() async {
215	        final raw = _phoneCtrl.text.trim().replaceAll(RegExp(r'\s+'), '');
216	        if (raw.isEmpty) throw Exception('Enter a phone number first.');
217	        final full = '${_country.dialCode}$raw';
218	        await _auth.verifyPhoneNumber(
219	          phoneNumber: full,
220	          forceResendingToken: _resendToken,
221	          verificationCompleted: (cred) => _auth.signInWithCredential(cred),
222	          verificationFailed: (e) {
223	            if (mounted) {
224	              setState(() => _error = _label(e));
225	            }
226	          },
227	          codeSent: (id, resend) {
228	            if (mounted) {
229	              setState(() {
230	                _verificationId = id;
231	                _resendToken = resend;
232	                _codeSent = true;
233	                _error = null;
234	              });
235	            }
236	          },
237	          codeAutoRetrievalTimeout: (_) {},
238	          timeout: const Duration(seconds: 60),
239	        );
240	      });
241	
242	  // ─── Phone: confirm OTP ──────────────────────────────────────────────────
243	  Future<void> _confirmOtp() => _run(() async {
244	        final id = _verificationId;
245	        final code = _otpCtrl.text.trim();
246	        if (id == null || code.isEmpty) throw Exception('Enter the 6-digit code sent to your phone.');
247	        final cred = PhoneAuthProvider.credential(verificationId: id, smsCode: code);
248	        await _auth.signInWithCredential(cred);
249	      });
250	
251	  // ─── Resend ──────────────────────────────────────────────────────────────
252	  void _resetPhone() => setState(() {
253	        _codeSent = false;
254	        _verificationId = null;
255	        _otpCtrl.clear();
256	        _error = null;
257	      });
