458	class _GoogleGPainter extends CustomPainter {
459	  @override
460	  void paint(Canvas canvas, Size size) {
461	    const colors = [Color(0xFF4285F4), Color(0xFF34A853), Color(0xFFFBBC05), Color(0xFFEA4335)];
462	    final center = Offset(size.width / 2, size.height / 2);
463	    final r = size.width / 2;
464	    final sweep = (2 * 3.14159265) / 4;
465	    final paint = Paint()..style = PaintingStyle.stroke..strokeWidth = size.width * 0.28;
466	    for (int i = 0; i < 4; i++) {
467	      paint.color = colors[i];
468	      canvas.drawArc(Rect.fromCircle(center: center, radius: r * 0.7),
469	          -3.14159265 / 2 + i * sweep, sweep - 0.08, false, paint);
470	    }
471	    // horizontal bar
472	    paint
473	      ..color = Color(0xFF4285F4)
474	      ..strokeWidth = size.width * 0.28;
475	    canvas.drawLine(
476	      Offset(center.dx, center.dy),
477	      Offset(size.width, center.dy),
478	      paint,
479	    );
480	  }
481	
482	  @override
483	  bool shouldRepaint(covariant CustomPainter old) => false;
484	}
